using Microsoft.OpenApi.Models;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new OpenApiInfo { Title = "Credito Modern API", Version = "v1" });
    options.AddSecurityDefinition(
        "Bearer",
        new OpenApiSecurityScheme
        {
            Name = "Authorization",
            Type = SecuritySchemeType.Http,
            Scheme = "bearer",
            BearerFormat = "JWT",
            In = ParameterLocation.Header,
            Description =
                "JWT de acceso (audience de acceso) con claims vendix:oficina_id, vendix:usuario_id (opcional vendix:usuario_oficina_id) y roles MAESTRO en ClaimTypes.Role. Obtén pares access+refresh con POST /api/v1/auth/login o POST /api/v1/auth/refresh; en Development local opcionalmente POST /api/v1/dev/token (solo si Hosting:AllowDevToken es true).",
        });
    options.AddSecurityRequirement(
        new OpenApiSecurityRequirement
        {
            {
                new OpenApiSecurityScheme
                {
                    Reference = new OpenApiReference { Type = ReferenceType.SecurityScheme, Id = "Bearer" },
                },
                Array.Empty<string>()
            },
        });
});

var healthChecksBuilder = builder.Services.AddHealthChecks()
    .AddCheck("self", () => HealthCheckResult.Healthy());
var sqlConnForHealth = builder.Configuration["CreditoDatabase:ConnectionString"];
if (!string.IsNullOrWhiteSpace(sqlConnForHealth))
{
    healthChecksBuilder.AddSqlServer(sqlConnForHealth, name: "database");
}

builder.Services.AddOptions<CreditoStorageOptions>()
    .BindConfiguration(CreditoStorageOptions.SectionName);
builder.Services.AddOptions<ArticuloStorageOptions>()
    .BindConfiguration(ArticuloStorageOptions.SectionName);

builder.Services.AddOptions<JwtOptions>()
    .BindConfiguration(JwtOptions.SectionName)
    .Validate(
        j => !string.IsNullOrWhiteSpace(j.SigningKey)
            && Encoding.UTF8.GetBytes(j.SigningKey).Length >= 32
            && j.AccessTokenLifetimeHours >= 1
            && j.AccessTokenLifetimeHours <= 168
            && !string.IsNullOrWhiteSpace(j.RefreshAudience)
            && j.RefreshTokenLifetimeDays >= 1
            && j.RefreshTokenLifetimeDays <= 90
            && j.RefreshTokenVersion >= 1
            && j.RefreshTokenVersion <= 999_999,
        "Jwt: SigningKey (≥32 bytes UTF-8), AccessTokenLifetimeHours (1-168), RefreshAudience no vacío, RefreshTokenLifetimeDays (1-90) y RefreshTokenVersion (1-999999) son obligatorios.")
    .ValidateOnStart();

builder.Services.AddSingleton<JwtTokenIssuer>();
builder.Services.AddSingleton<RefreshTokenValidator>();

builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer();

builder.Services
    .AddOptions<JwtBearerOptions>(JwtBearerDefaults.AuthenticationScheme)
    .Configure<Microsoft.Extensions.Options.IOptions<JwtOptions>>((options, jwtApp) =>
    {
        var j = jwtApp.Value;
        options.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuerSigningKey = true,
            IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(j.SigningKey)),
            ValidateIssuer = true,
            ValidIssuer = j.Issuer,
            ValidateAudience = true,
            ValidAudience = j.Audience,
            ValidateLifetime = true,
            ClockSkew = TimeSpan.FromMinutes(2),
        };
    });

builder.Services.AddAuthorization(options =>
{
    options.AddPolicy(CreditoAuthorizationPolicies.CreditoUser, static policy => policy.RequireAuthenticatedUser());
    options.AddPolicy(
        CreditoAuthorizationPolicies.CreditoRolAdministrador,
        static policy =>
        {
            policy.RequireAuthenticatedUser();
            policy.RequireRole(CreditoAuthorizationPolicies.RolesAdministrador);
        });
    options.AddPolicy(
        CreditoAuthorizationPolicies.CreditoRolEncargado,
        static policy =>
        {
            policy.RequireAuthenticatedUser();
            policy.RequireRole(CreditoAuthorizationPolicies.RolDenominacionEncargado);
        });
    options.AddPolicy(
        CreditoAuthorizationPolicies.CreditoRolAprobador1,
        static policy =>
        {
            policy.RequireAuthenticatedUser();
            policy.RequireRole(CreditoAuthorizationPolicies.RolDenominacionAprobador1);
        });
    options.AddPolicy(
        CreditoAuthorizationPolicies.CreditoRolAprobador1OAdministrador,
        static policy =>
        {
            policy.RequireAuthenticatedUser();
            policy.RequireRole(CreditoAuthorizationPolicies.RolesAprobador1OAdministrador);
        });
    options.AddPolicy(
        CreditoAuthorizationPolicies.CreditoRolSoloAdministrador,
        static policy =>
        {
            policy.RequireAuthenticatedUser();
            policy.RequireRole(CreditoAuthorizationPolicies.RolesAdministrador);
        });
    options.AddPolicy(
        CreditoAuthorizationPolicies.CreditoRolEncargadoOAdministrador,
        static policy =>
        {
            policy.RequireAuthenticatedUser();
            policy.RequireRole(CreditoAuthorizationPolicies.RolesEncargadoOAdministrador);
        });
    options.AddPolicy(
        CreditoAuthorizationPolicies.CreditoRolOperador,
        static policy =>
        {
            policy.RequireAuthenticatedUser();
            policy.RequireAssertion(ctx =>
            {
                var roles = ctx.User
                    .FindAll(System.Security.Claims.ClaimTypes.Role)
                    .Select(c => c.Value.Trim().ToUpperInvariant())
                    .ToList();
                if (roles.Count == 0)
                {
                    return false;
                }

                return roles.Any(r => r != CreditoAuthorizationPolicies.RolDenominacionLectura);
            });
        });
});

builder.Services.AddModernInfrastructure(builder.Configuration);
builder.Services.AddMemoryCache();
builder.AddCreditoHostSecurity();

builder.Services.ConfigureHttpJsonOptions(options =>
{
    options.SerializerOptions.PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase;
});

var app = builder.Build();

app.Use(async (context, next) =>
{
    var correlationId = context.Request.Headers["X-Correlation-ID"].ToString();
    if (string.IsNullOrWhiteSpace(correlationId))
    {
        correlationId = Guid.NewGuid().ToString("N");
    }

    context.Response.Headers["X-Correlation-ID"] = correlationId;
    context.Items["CorrelationId"] = correlationId;
    await next().ConfigureAwait(false);
});

if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI();
}

app.UseCreditoHostSecurity();
app.UseAuthentication();
app.UseAuthorization();

app.MapHealthChecks("/health", new HealthCheckOptions
{
    ResponseWriter = async (context, report) =>
    {
        context.Response.ContentType = "application/json";
        var payload = System.Text.Json.JsonSerializer.Serialize(new
        {
            status = report.Status.ToString(),
            checks = report.Entries.Select(e => new { name = e.Key, status = e.Value.Status.ToString() }),
        });
        await context.Response.WriteAsync(payload);
    },
});

app.MapGet("/api/v1/database-time", async Task<Results<Ok<DatabaseTimeResponse>, ProblemHttpResult>> (
    IDatabaseTimeProvider clock,
    ILoggerFactory loggerFactory,
    IHostEnvironment env,
    CancellationToken ct) =>
{
    var log = loggerFactory.CreateLogger("DatabaseTime");
    try
    {
        var databaseTime = await clock.GetServerTimeAsync(ct).ConfigureAwait(false);
        return TypedResults.Ok(new DatabaseTimeResponse(databaseTime));
    }
    catch (InvalidOperationException ex)
    {
        log.LogWarning(ex, "Cadena de conexión no configurada");
        return TypedResults.Problem(
            detail: ex.Message,
            statusCode: StatusCodes.Status503ServiceUnavailable,
            title: "Configuración incompleta");
    }
    catch (DbException ex)
    {
        log.LogError(ex, "Error al abrir SQL o ejecutar usp_FechaBD");
        var detail =
            "No se pudo conectar a SQL Server o falló la consulta. Revisa CreditoDatabase:ConnectionString (user-secrets), que la instancia esté en marcha y usuario/clave. En instancias locales a veces hace falta añadir Encrypt=False;TrustServerCertificate=True.";
        if (env.IsDevelopment())
            detail += $" Detalle: {ex.Message}";
        return TypedResults.Problem(
            detail: detail,
            statusCode: StatusCodes.Status503ServiceUnavailable,
            title: "Error de base de datos");
    }
})
.WithName("DatabaseTime")
.WithTags("read-only")
.Produces<DatabaseTimeResponse>(StatusCodes.Status200OK, "application/json")
.ProducesProblem(StatusCodes.Status503ServiceUnavailable);

app.MapPost("/api/v1/auth/refresh", async Task<Results<Ok<LoginTokenResponse>, ProblemHttpResult>> (
    RefreshTokenRequest body,
    RefreshTokenValidator refreshValidator,
    ILegacyLoginService loginService,
    JwtTokenIssuer jwt,
    IOptions<JwtOptions> jwtOpts,
    ILoggerFactory loggerFactory,
    IHostEnvironment env,
    CancellationToken ct) =>
{
    var log = loggerFactory.CreateLogger("AuthRefresh");
    if (string.IsNullOrWhiteSpace(body.RefreshToken))
    {
        return TypedResults.Problem(
            statusCode: StatusCodes.Status400BadRequest,
            title: "Solicitud inválida",
            detail: "refreshToken es obligatorio.");
    }

    if (!refreshValidator.TryValidate(body.RefreshToken, out var usuarioId, out var oficinaId, out var usuarioOficinaId))
    {
        return TypedResults.Problem(
            statusCode: StatusCodes.Status401Unauthorized,
            title: "No autorizado",
            detail: "Refresh token inválido o expirado.");
    }

    try
    {
        var roles = await loginService.GetUsuarioRolesAsync(usuarioId, oficinaId, ct).ConfigureAwait(false);
        var accessLifetime = TimeSpan.FromHours(jwtOpts.Value.AccessTokenLifetimeHours);
        var refreshLifetime = TimeSpan.FromDays(jwtOpts.Value.RefreshTokenLifetimeDays);
        var accessToken = jwt.CreateAccessToken(usuarioId, oficinaId, accessLifetime, usuarioOficinaId, roles);
        var refreshToken = jwt.CreateRefreshToken(usuarioId, oficinaId, usuarioOficinaId);
        return TypedResults.Ok(
            new LoginTokenResponse(
                accessToken,
                (int)accessLifetime.TotalSeconds,
                refreshToken,
                (int)refreshLifetime.TotalSeconds,
                usuarioId,
                oficinaId,
                usuarioOficinaId ?? 0));
    }
    catch (InvalidOperationException ex)
    {
        log.LogWarning(ex, "Cadena de conexión no configurada");
        return TypedResults.Problem(
            detail: ex.Message,
            statusCode: StatusCodes.Status503ServiceUnavailable,
            title: "Configuración incompleta");
    }
    catch (DbException ex)
    {
        log.LogError(ex, "Error SQL al refrescar roles");
        var detail = "No se pudo consultar roles en SQL Server.";
        if (env.IsDevelopment())
            detail += $" Detalle: {ex.Message}";
        return TypedResults.Problem(
            detail: detail,
            statusCode: StatusCodes.Status503ServiceUnavailable,
            title: "Error de base de datos");
    }
})
.WithName("AuthRefresh")
.WithTags("auth")
.RequireRateLimiting("auth-refresh")
.Produces<LoginTokenResponse>(StatusCodes.Status200OK, "application/json")
.ProducesProblem(StatusCodes.Status400BadRequest)
.ProducesProblem(StatusCodes.Status401Unauthorized)
.ProducesProblem(StatusCodes.Status429TooManyRequests)
.ProducesProblem(StatusCodes.Status503ServiceUnavailable);

