            {
                var response = await transferenciaWrite
                    .ConfirmarAsync(body.OficinaId, body.TransferenciaId, ct)
                    .ConfigureAwait(false);
                if (!response.Success)
                {
                    return TypedResults.Problem(
                        statusCode: StatusCodes.Status409Conflict,
                        title: "No confirmada",
