            }
            catch (InvalidOperationException ex)
            {
                log.LogWarning(ex, "Cadena de conexión no configurada");
                return TypedResults.Problem(
                    detail: ex.Message,
                    statusCode: StatusCodes.Status503ServiceUnavailable,
